  add({
    "tutor.opener.0": ["Đọc lại đề một lượt nhé. Đề cho em biết gì, và hỏi em điều gì?", "Read the question again. What does it tell you, and what does it ask?"],
    "tutor.opener.1": ["Nếu phải nói bài này bằng một câu của chính em, em sẽ nói thế nào?", "How would you say this problem in one sentence of your own?"],
    "tutor.opener.2": ["Em đã gặp bài nào giống bài này chưa? Cách làm lần đó có dùng được không?", "Have you seen a problem like this before? Would that method work here?"],
    "tutor.hint.done": ["Em đã có đủ gợi ý rồi. Viết từng bước ra giấy, kiểm tra từng bước một nhé.", "You have all the hints now. Write each step on paper and check them one by one."],
    "tutor.diag.sign": ["Con số của em gần đúng rồi, nhưng hãy kiểm tra lại DẤU. Kết quả nên âm hay dương? Vì sao?", "Your number is close, but check the SIGN. Should the answer be negative or positive? Why?"],
    "tutor.diag.place": ["Các chữ số có vẻ đúng, nhưng giá trị bị lệch 10 hoặc 100 lần. Em thử ước lượng xem đáp án khoảng bao nhiêu?", "The digits look right, but the size is out by 10 or 100. Can you estimate roughly what the answer should be?"],
    "tutor.diag.reciprocal": ["Hình như em đã lật ngược phân số. Phép tính nào cần lấy nghịch đảo, phép tính nào thì không?", "It looks like the fraction got flipped. Which operation needs the reciprocal, and which doesn't?"],
    "tutor.diag.close": ["Rất gần rồi! Kiểm tra lại bước tính cuối cùng hoặc cách làm tròn xem.", "So close! Check your last step or your rounding."],
    "tutor.wrong.mc": ["Phương án đó là một nhầm lẫn rất hay gặp. Em thử loại trừ: phương án nào chắc chắn sai, vì sao?", "That option is a very common mix-up. Try eliminating: which options are definitely wrong, and why?"],
    "tutor.wrong.1": ["Chưa đúng — nhưng sai là một phần của học!", "Not yet — but mistakes are part of learning!"],
    "tutor.wrong.2": ["Thử dùng gợi ý nhé.", "Try using a hint."],
    "tutor.wrong.3": ["Em đã rất kiên trì. Em có thể xem lời giải để hiểu cách làm, rồi thử lại câu tương tự sau.", "You kept going — well done. Look at the solution to understand the method, then try a similar one later."],
    "tutor.right.fixed": ["Tuyệt! Em đã tự sửa được lỗi — đó chính là cách người giỏi toán học. Lần sai trước, em đã nhầm ở đâu?", "Brilliant! You fixed your own mistake — that's how good mathematicians learn. Where did you slip last time?"],
    "tutor.right.hint": ["Đúng rồi! Gợi ý nào giúp em nhiều nhất? Lần sau em có tự hỏi mình câu đó được không?", "Correct! Which hint helped most? Could you ask yourself that question next time?"],
    "tutor.right.hard": ["Xuất sắc — câu khó mà em làm ngay! Em có thể giải thích cách làm cho một bạn khác không?", "Excellent — a hard one, first time! Could you explain your method to a friend?"],
    "tutor.right.0": ["Chính xác!", "Exactly right!"], "tutor.right.1": ["Đúng rồi, gọn gàng!", "Correct and neat!"],
    "tutor.right.2": ["Chuẩn! Em tự tin hơn rồi đấy.", "Spot on! You're getting more confident."],
    "tutor.ask.lost": ["Không sao, mình chia nhỏ ra nhé. Em gạch chân các con số trong đề. Mỗi con số đó cho biết điều gì?", "That's OK, let's break it down. Underline the numbers in the question. What does each one tell you?"],
    "tutor.ask.start": ["Hãy thử với một trường hợp nhỏ, dễ hơn. Nếu các số trong đề nhỏ hơn, em sẽ làm thế nào? Rồi áp dụng lại.", "Try a smaller, easier case first. If the numbers were smaller, what would you do? Then apply it here."],
    "tutor.ask.formula": ["Em nhớ những công thức nào liên quan đến chủ đề này? Viết ra rồi xem đại lượng nào đề đã cho, đại lượng nào cần tìm.", "Which formulas do you know for this topic? Write them down, then mark what's given and what you need to find."],
    "tutor.ask.answer": ["Cú tin em tự tìm được! Em đang kẹt ở bước nào? Kể Cú nghe bước em đã làm.", "Owl believes you can find it! Which step are you stuck on? Tell me what you've done so far."],
    "tutor.ask.draw": ["Vẽ hình là ý hay! Em ghi các số đo đã biết lên hình, rồi đánh dấu điều cần tìm bằng dấu ?.", "Drawing is a great idea! Label the known measurements, then mark what you need with a ?."],
    "tutor.ask.check": ["Có cách nào kiểm tra ngược lại không? Ví dụ thay đáp án vào đề, hoặc ước lượng xem có hợp lý không.", "Can you check it backwards? For example, put your answer back into the question, or estimate whether it's sensible."],
    "tutor.ask.empty": ["Em cứ viết suy nghĩ của mình ra, dù chưa chắc chắn. Cú sẽ hỏi lại để em tự tìm ra hướng đi.", "Just write what you're thinking, even if you're unsure. Owl will ask questions to help you find the way."],
    "tutor.ask.number": ["Em vừa nêu một con số/ phép tính. Con số đó đến từ đâu trong đề? Nếu đúng, bước tiếp theo sẽ là gì?", "You wrote a number or calculation. Where does it come from in the question? If it's right, what's the next step?"],
    "tutor.ask.hint": ["Cú hỏi em nhé: {hint}", "Owl's question for you: {hint}"],
    "tutor.ask.why": ["Ý của em thú vị đấy. Em có thể giải thích vì sao em nghĩ vậy không?", "Interesting idea! Can you explain why you think so?"],
    "tutor.howto": ["Em đã đọc phần “📖 Đề bài yêu cầu gì?” chưa? Bấm vào đó xem đề muốn em tìm gì và nhập thế nào nhé.", "Have you read “📖 What do I do?” yet? Tap it to see what the question wants and how to type your answer."]
  });

