    "play.howto.task": ["Nhiệm vụ", "Your task"], "play.howto.format": ["Cách nhập đáp án", "How to enter your answer"],
    "play.howto.free": ["Xem hướng dẫn không bị trừ điểm và không tính là gợi ý.", "Reading this costs no points and doesn't count as a hint."],
    "play.howto.time": ["Lần mở đầu tiên khi còn trong thời gian được cộng thêm {s} giây đọc đề.", "Opening it the first time, within the time, adds {s} seconds of reading time."],
    "play.howto.bonus": ["+{s} giây đọc đề", "+{s}s reading time"],
    "howto.mc": ["Chọn MỘT đáp án rồi bấm Kiểm tra.", "Choose ONE answer, then press Check."],
    "howto.multi": ["Chọn TẤT CẢ các đáp án đúng (có thể nhiều hơn một), rồi bấm Kiểm tra.", "Choose ALL the correct answers (there may be more than one), then press Check."],
    "howto.num": ["Nhập một số. Số thập phân viết 2,5 hay 2.5 đều được; số âm gõ dấu - ở trước.", "Type one number. Decimals can be written 2.5 or 2,5; for a negative number put - in front."],
    "howto.frac": ["Nhập phân số dạng a/b (như 3/4) hoặc hỗn số có dấu cách (như 2 1/3). Phân số bằng nhau đều được chấm đúng.", "Type a fraction as a/b (like 3/4) or a mixed number with a space (like 2 1/3). Equivalent fractions are marked correct."],
    "howto.fracText": ["Nhập phân số tối giản dạng a/b, dùng dấu gạch chéo /.", "Type the fraction in its simplest form as a/b, using a slash /."],
    "howto.anyOf": ["Câu này có nhiều hơn một đáp án đúng — nhập MỘT trong số đó là đủ.", "This question has more than one correct answer — typing just ONE of them is enough."],
    "howto.round": ["Làm tròn đến {n} chữ số thập phân.", "Round your answer to {n} d.p. (decimal places)."],
    "howto.roundInt": ["Làm tròn đến số nguyên gần nhất.", "Round to the nearest whole number."],
